mapper.select:
/*selectMasterCmClDeptClosingList*/
SELECT A.DEPT_CODE , (SELECT B.TEXT2 FROM ICOMCOD1 B WHERE B.TYPE='TX06' AND B.FLAG='Y' AND B.CODE=A.DEPT_CODE) AS DEPT_NAME , A.CLOSE_YYYYMM , A.CLOSE_YN , CHANGE_DATE , CHANGE_TIME , B.AR_AMT , C.AP_AMT FROM BNTCLOSE A /* 부서별 마감설정 */ , (SELECT B.DEPT_CODE ,SUM(B.TOT_AMT) AS AR_AMT FROM KEPTARDT B WHERE B.IF_SEND_FLAG='Y' AND B.AR_CLOSE_MONTH = #{st_from_date} GROUP BY B.DEPT_CODE ) B , (SELECT B.DEPT_CODE ,SUM(B.TOT_AMT) AS AP_AMT FROM KEPTAPDT B WHERE B.IF_SEND_FLAG='Y' AND B.AP_CLOSE_MONTH = #{st_from_date} GROUP BY B.DEPT_CODE ) C WHERE 1=1 AND A.CLOSE_YYYYMM = #{st_from_date} AND A.DEPT_CODE = B.DEPT_CODE(+) AND A.DEPT_CODE = C.DEPT_CODE(+)
AND A.DEPT_CODE = #{st_dept}
ORDER BY A.DEPT_CODE

mapper.update:
/*updateMasterCmClDeptClosingList*/

		UPDATE BNTCLOSE /* 마스터 코드관리 */
		SET CLOSE_YN = #{CLOSE_YN}
		  , CHANGE_DATE = TO_CHAR(SYSDATE, 'YYYYMMDD')
		  , CHANGE_TIME = TO_CHAR(SYSDATE, 'HH24MISS')
		  , CHANGE_USER_ID = #{st_user_id}
		WHERE 1=1
		AND DEPT_CODE = #{DEPT_CODE}
		AND CLOSE_YYYYMM = #{CLOSE_YYYYMM}
